pub(super) fn p2p3_readiness__missing_product_input_refs(
    mut trust_dir: Value,
    mut workflow_dir: Value,
) -> Result<Value> {
    let mut expected: Value;
    let mut gaps: Value;
    let mut root: Value;
    expected = {
        let mut object = json!({});
        object[values::text(&trust_dir)] = Value::Array(vec![
            json!("aete-score.json"),
            json!("artifact-resolver-map.json"),
            json!("doctor-report.json"),
            json!("adapter-capability-manifest.json"),
            json!("adapter-conformance-report.json"),
            json!("canonical-identity-index.json"),
            json!("retry-aggregation.json"),
            json!("trust-summary.md"),
        ]);
        object[values::text(&workflow_dir)] = Value::Array(vec![
            json!("requirement-evidence-alignment.json"),
            json!("workflow-task-seed.json"),
            json!("workflow-acceptance-record.json"),
            json!("workflow-evidence.jsonl"),
            json!("workflow-docs-stale.json"),
            json!("workflow-birdseye-map.json"),
            json!("shipyard-run-evidence.json"),
        ]);
        object
    };
    gaps = Value::Array(vec![]);
    for current in sequence(&members(&expected, "items")?)? {
        let bound_values = current;
        let mut base = indexed(&bound_values, &json!(0))?;
        let mut names = indexed(&bound_values, &json!(1))?;
        root = (if equal(&base, &trust_dir) {
            json!("trust")
        } else {
            json!("workflow")
        });
        for current in sequence(&names)? {
            let mut name = current;
            if !(truth(&json!(to_path(&join_path(&base, &name)).exists()))) {
                {
                    let incoming = Value::Object(
                        [
                            ("root".into(), root.clone()),
                            ("artifact_ref".into(), name.clone()),
                            ("reason".into(), json!("expected input artifact missing")),
                        ]
                        .into_iter()
                        .collect(),
                    );
                    edit(&mut gaps, "append", incoming)?;
                }
            }
        }
    }
    return Ok(gaps.clone());
}

