pub(super) fn p2p3_readiness__product_hard_dqs(
    mut alignment: Value,
    mut doctor: Value,
) -> Result<Value> {
    let mut hard_dqs: Value;
    hard_dqs = Value::Array(vec![]);
    for current in sequence(&Value::Array(vec![
        get(&alignment, &json!("hard_dqs"), Value::Null),
        get(&doctor, &json!("hard_dqs"), Value::Null),
    ]))? {
        let mut source = current;
        if (source.clone().is_array()) {
            {
                let incoming = {
                    let mut collected_values = Vec::new();
                    for current in sequence(&source)? {
                        let mut item = current;
                        if !(item.clone().is_object()) {
                            continue;
                        }
                        collected_values.push(p2p3_readiness__canonical_gap_item(
                            item.clone(),
                            json!("hard_dq"),
                            json!("hard_dq"),
                        )?);
                    }
                    Value::Array(collected_values)
                };
                edit(&mut hard_dqs, "extend", incoming)?;
            }
        }
    }
    for current in sequence(
        &(if (get(&doctor, &json!("findings"), Value::Null).is_array()) {
            get(&doctor, &json!("findings"), Value::Array(vec![]))
        } else {
            Value::Array(vec![])
        }),
    )? {
        let mut finding = current;
        if (finding.clone().is_object())
            && (contains(
                &unique(vec![
                    json!("hard"),
                    json!("hard_dq"),
                    json!("block"),
                    json!("critical"),
                ]),
                &json!(values::text(&{
                    let first = get(&finding, &json!("severity"), Value::Null);
                    if truth(&first) {
                        first
                    } else {
                        {
                            let first = get(&finding, &json!("effect"), Value::Null);
                            if truth(&first) { first } else { json!("") }
                        }
                    }
                })),
            ))
        {
            {
                let incoming = p2p3_readiness__canonical_gap_item(
                    finding.clone(),
                    json!(values::text(&{
                        let first = get(&finding, &json!("code"), Value::Null);
                        if truth(&first) {
                            first
                        } else {
                            json!("doctor_hard_dq")
                        }
                    })),
                    json!("hard_dq"),
                )?;
                edit(&mut hard_dqs, "append", incoming)?;
            }
        }
    }
    return Ok(hard_dqs.clone());
}

pub(super) fn p2p3_readiness__product_overall_status(
    mut input_gaps: Value,
    mut doctor_findings: Value,
    mut unverified_acceptance: Value,
) -> Result<Value> {
    if truth(&input_gaps) {
        return Ok(json!("hold"));
    }
    if (truth(&doctor_findings)) || (truth(&unverified_acceptance)) {
        return Ok(json!("conditional"));
    }
    return Ok(json!("go"));
}

pub(super) fn p2p3_readiness__product_readiness_gates(
    mut input_gaps: Value,
    mut doctor_findings: Value,
    mut unverified_acceptance: Value,
) -> Result<Value> {
    let mut prg2_status: Value;
    let mut prg3_status: Value;
    let mut prg4_status: Value;
    prg2_status = (if truth(&builtin(
        "any",
        &[{
            let mut collected_values = Vec::new();
            for current in sequence(&input_gaps)? {
                let mut gap = current;
                collected_values.push(json!(equal(
                    &indexed(&gap, &json!("root"))?,
                    &json!("trust")
                )));
            }
            Value::Array(collected_values)
        }],
    )?) {
        json!("hold")
    } else {
        json!("covered_by_fixture")
    });
    prg3_status = (if truth(&input_gaps) {
        json!("hold")
    } else {
        (if (truth(&doctor_findings)) || (truth(&unverified_acceptance)) {
            json!("conditional")
        } else {
            json!("covered_by_fixture")
        })
    });
    prg4_status = (if truth(&builtin(
        "any",
        &[{
            let mut collected_values = Vec::new();
            for current in sequence(&input_gaps)? {
                let mut gap = current;
                collected_values.push(json!(equal(
                    &indexed(&gap, &json!("root"))?,
                    &json!("workflow")
                )));
            }
            Value::Array(collected_values)
        }],
    )?) {
        json!("hold")
    } else {
        json!("covered_by_artifact")
    });
    return Ok(Value::Array(vec![
        p2p3_readiness__gate(
            json!("PRG-0"),
            json!("Prototype"),
            json!("pass"),
            Value::Array(vec![json!("P0a golden fixture is executable.")]),
        )?,
        p2p3_readiness__gate(
            json!("PRG-1"),
            json!("Internal Alpha"),
            json!("covered_by_fixture"),
            Value::Array(vec![json!("P0b QEG export fixture is executable.")]),
        )?,
        p2p3_readiness__gate(
            json!("PRG-2"),
            json!("Private Beta"),
            prg2_status.clone(),
            Value::Array(vec![json!("Adapter conformance report is generated.")]),
        )?,
        p2p3_readiness__gate(
            json!("PRG-3"),
            json!("Team GA"),
            prg3_status.clone(),
            Value::Array(vec![json!(
                "QEG export, doctor, summary, and docs evidence are linked."
            )]),
        )?,
        p2p3_readiness__gate(
            json!("PRG-4"),
            json!("Enterprise Ready"),
            prg4_status.clone(),
            Value::Array(vec![json!(
                "RBAC/read model/support/customer docs artifacts are present."
            )]),
        )?,
        p2p3_readiness__gate(
            json!("PRG-5"),
            json!("Regulated Ready"),
            (if !(truth(&input_gaps)) {
                json!("covered_by_artifact")
            } else {
                json!("hold")
            }),
            Value::Array(vec![json!(
                "Trust, privacy, audit, and assurance artifacts are present."
            )]),
        )?,
        p2p3_readiness__gate(
            json!("PRG-6"),
            json!("Enterprise Product Ready"),
            (if !(truth(&input_gaps)) {
                json!("covered_by_artifact")
            } else {
                json!("hold")
            }),
            Value::Array(vec![json!(
                "Enterprise metrics and governance reports are present."
            )]),
        )?,
    ]));
}

pub(super) fn p2p3_readiness__product_soft_gaps(
    mut input_gaps: Value,
    mut doctor: Value,
    mut alignment: Value,
    mut unverified_acceptance: Value,
) -> Result<Value> {
    let mut artifact_ref: Value;
    let mut soft_gaps: Value;
    soft_gaps = Value::Array(vec![]);
    for current in sequence(&input_gaps)? {
        let mut gap = current;
        artifact_ref = json!(values::text(&get(
            &gap,
            &json!("artifact_ref"),
            json!("missing-input")
        )));
        {
            let incoming = Value::Object(
                [
                    ("code".into(), json!("missing_input_artifact")),
                    ("severity".into(), json!("medium")),
                    (
                        "message".into(),
                        json!(values::text(&{
                            let first = get(&gap, &json!("reason"), Value::Null);
                            if truth(&first) {
                                first
                            } else {
                                json!("expected input artifact missing")
                            }
                        })),
                    ),
                    ("artifact_ref".into(), artifact_ref.clone()),
                    (
                        "root".into(),
                        json!(values::text(&{
                            let first = get(&gap, &json!("root"), Value::Null);
                            if truth(&first) {
                                first
                            } else {
                                json!("unknown")
                            }
                        })),
                    ),
                    ("readiness_effect".into(), json!("hold")),
                    (
                        "sourceRefs".into(),
                        Value::Array(vec![artifact_ref.clone()]),
                    ),
                ]
                .into_iter()
                .collect(),
            );
            edit(&mut soft_gaps, "append", incoming)?;
        }
    }
    for current in sequence(
        &(if (get(&doctor, &json!("findings"), Value::Null).is_array()) {
            get(&doctor, &json!("findings"), Value::Array(vec![]))
        } else {
            Value::Array(vec![])
        }),
    )? {
        let mut finding = current;
        if (finding.clone().is_object())
            && (!contains(
                &unique(vec![
                    json!("hard"),
                    json!("hard_dq"),
                    json!("block"),
                    json!("critical"),
                ]),
                &json!(values::text(&{
                    let first = get(&finding, &json!("severity"), Value::Null);
                    if truth(&first) {
                        first
                    } else {
                        {
                            let first = get(&finding, &json!("effect"), Value::Null);
                            if truth(&first) { first } else { json!("") }
                        }
                    }
                })),
            ))
        {
            {
                let incoming = p2p3_readiness__canonical_gap_item(
                    finding.clone(),
                    json!(values::text(&{
                        let first = get(&finding, &json!("code"), Value::Null);
                        if truth(&first) {
                            first
                        } else {
                            json!("doctor_finding")
                        }
                    })),
                    json!("soft_gap"),
                )?;
                edit(&mut soft_gaps, "append", incoming)?;
            }
        }
    }
    if (truth(&unverified_acceptance))
        && (!(truth(&builtin(
            "any",
            &[{
                let mut collected_values = Vec::new();
                for current in sequence(&soft_gaps)? {
                    let mut gap = current;
                    collected_values.push(json!(equal(
                        &get(&gap, &json!("code"), Value::Null),
                        &json!("unverified_acceptance")
                    )));
                }
                Value::Array(collected_values)
            }],
        )?)))
    {
        {
            let incoming = Value::Object(
                [
                    ("code".into(), json!("unverified_acceptance")),
                    ("severity".into(), json!("medium")),
                    (
                        "message".into(),
                        json!(format!(
                            "{} acceptance items are not verified by evidence.",
                            values::text(&unverified_acceptance)
                        )),
                    ),
                    ("readiness_effect".into(), json!("conditional")),
                    ("sourceRefs".into(), {
                        let first = p2p3_readiness__extract_source_refs(alignment.clone())?;
                        if truth(&first) {
                            first
                        } else {
                            Value::Array(vec![json!("requirement-evidence-alignment.json")])
                        }
                    }),
                ]
                .into_iter()
                .collect(),
            );
            edit(&mut soft_gaps, "append", incoming)?;
        }
    }
    return Ok(soft_gaps.clone());
}

pub(super) fn p2p3_readiness__product_source_refs(
    mut source_refs: Value,
    mut generated_refs: Value,
    mut alignment: Value,
    mut doctor: Value,
    mut soft_gaps: Value,
    mut hard_dqs: Value,
    mut unsupported_claims: Value,
    mut contradictions: Value,
) -> Result<Value> {
    let mut refs: Value;
    refs = arithmetic(
        &builtin("list", &[source_refs.clone()])?,
        &builtin("list", &[generated_refs.clone()])?,
        "+",
    )?;
    {
        let incoming = p2p3_readiness__extract_source_refs(alignment.clone())?;
        edit(&mut refs, "extend", incoming)?;
    }
    {
        let incoming = p2p3_readiness__extract_source_refs(doctor.clone())?;
        edit(&mut refs, "extend", incoming)?;
    }
    for current in sequence(&arithmetic(
        &arithmetic(
            &arithmetic(&soft_gaps, &hard_dqs, "+")?,
            &unsupported_claims,
            "+",
        )?,
        &contradictions,
        "+",
    )?)? {
        let mut item = current;
        {
            let incoming = p2p3_readiness__extract_source_refs(item.clone())?;
            edit(&mut refs, "extend", incoming)?;
        }
    }
    return Ok(sorted(
        &{
            let mut collected_values = Vec::new();
            for current in sequence(&refs)? {
                let mut r#ref = current;
                if !(truth(&json!(values::text(&r#ref)))) {
                    continue;
                }
                collected_values.push(json!(values::text(&r#ref)));
            }
            unique(collected_values)
        },
        |v: &Value| Ok(v.clone()),
        false,
    )?);
}

pub(super) fn p2p3_readiness__product_unsupported_claims(mut alignment: Value) -> Result<Value> {
    let mut claims: Value;
    let mut result: Value;
    let mut status: Value;
    claims = get(&alignment, &json!("unsupported_claims"), Value::Null);
    if (claims.clone().is_array()) {
        return Ok({
            let mut collected_values = Vec::new();
            for current in sequence(&claims)? {
                let mut item = current;
                if !(item.clone().is_object()) {
                    continue;
                }
                collected_values.push(p2p3_readiness__canonical_gap_item(
                    item.clone(),
                    json!("unsupported_claim"),
                    json!("unsupported_claim"),
                )?);
            }
            Value::Array(collected_values)
        });
    }
    result = Value::Array(vec![]);
    for current in sequence(&Value::Array(vec![
        json!("claims"),
        json!("acceptance_items"),
        json!("requirements"),
    ]))? {
        let mut key = current;
        for current in sequence(
            &(if (get(&alignment, &key, Value::Null).is_array()) {
                get(&alignment, &key, Value::Array(vec![]))
            } else {
                Value::Array(vec![])
            }),
        )? {
            let mut item = current;
            if !(item.clone().is_object()) {
                continue;
            }
            status = json!(values::text(&{
                let first = get(&item, &json!("status"), Value::Null);
                if truth(&first) {
                    first
                } else {
                    {
                        let first = get(&item, &json!("support_status"), Value::Null);
                        if truth(&first) {
                            first
                        } else {
                            {
                                let first = get(&item, &json!("evidence_status"), Value::Null);
                                if truth(&first) { first } else { json!("") }
                            }
                        }
                    }
                }
            }));
            if contains(
                &unique(vec![
                    json!("unsupported"),
                    json!("missing_evidence"),
                    json!("unverified"),
                ]),
                &status,
            ) {
                {
                    let incoming = p2p3_readiness__canonical_gap_item(
                        item.clone(),
                        json!(values::text(&{
                            let first = get(&item, &json!("claim_id"), Value::Null);
                            if truth(&first) {
                                first
                            } else {
                                {
                                    let first = get(&item, &json!("id"), Value::Null);
                                    if truth(&first) { first } else { key.clone() }
                                }
                            }
                        })),
                        json!("unsupported_claim"),
                    )?;
                    edit(&mut result, "append", incoming)?;
                }
            }
        }
    }
    return Ok(result.clone());
}

pub(super) fn p2p3_readiness__safe_float(value: Value, default: Value) -> Result<Value> {
    Ok(number(&value).map_or(default, |n| json!(n)))
}

pub(super) fn p2p3_readiness__safe_int(value: Value, default: Value) -> Result<Value> {
    Ok(integer(&value).map_or(default, |n| json!(n)))
}

pub(super) fn p2p3_readiness__score_cap(
    mut cap_id: Value,
    mut max_score: Value,
    mut reason: Value,
) -> Result<Value> {
    return Ok(Value::Object(
        [
            ("cap_id".into(), cap_id.clone()),
            ("max_score".into(), max_score.clone()),
            ("reason".into(), reason.clone()),
        ]
        .into_iter()
        .collect(),
    ));
}

